const source=$('Preparar contexto sanitizado').item.json;
  let enrichment=$json.output??$json;
  if(typeof enrichment==='string'){
    try{enrichment=JSON.parse(enrichment);}
    catch{throw new Error('A IA não retornou JSON válido.');}
  }
  const asList=value=>Array.isArray(value)?value.map(String).filter(Boolean):[];
  const normalized={
    summary:String(enrichment.summary??'Resumo não gerado.'),
    businessPurpose:String(enrichment.businessPurpose??'Precisa de confirmação.'),
    inputs:asList(enrichment.inputs),
    outputs:asList(enrichment.outputs),
    integrations:asList(enrichment.integrations),
    risks:asList(enrichment.risks),
    troubleshootingSuggestions:asList(enrichment.troubleshootingSuggestions),
    reviewNotes:asList(enrichment.reviewNotes),
    confidence:['low','medium','high'].includes(enrichment.confidence)?enrichment.confidence:'low'
  };
  const section=(title,values)=>['## '+title,'',...(values.length?values.map(value=>'- '+value):['- Não identificado.']),''];
  const markdown=[
    '# Enriquecimento por IA','',
    '> Conteúdo gerado automaticamente. Exige revisão humana antes de promoção.','',
    '## Resumo','',normalized.summary,'',
    '## Finalidade de negócio','',normalized.businessPurpose,'',
    ...section('Entradas',normalized.inputs),
    ...section('Saídas',normalized.outputs),
    ...section('Integrações',normalized.integrations),
    ...section('Riscos',normalized.risks),
    ...section('Sugestões de troubleshooting',normalized.troubleshootingSuggestions),
    ...section('Pontos para revisão',normalized.reviewNotes),
    '## Confiança','',normalized.confidence
  ].join('\n');
  const {aiPrompt,...base}=source;
  const humanFiles={...(base.humanFiles??{})};
  const technicalFiles={...(base.technicalFiles??{})};
  if(base.documentationMode==='maintenance'){
    technicalFiles['generated/ai-change-analysis.md']=markdown;
  }else{
    humanFiles['docs/ai-enrichment.md']=markdown;
  }
  return {json:{
    ...base,
    humanFiles,
    technicalFiles,
    aiEnrichment:normalized,
    reviewRequired:true
  }};

const payloads = $input.all().map(item => item.json);
if (payloads.length === 0) throw new Error("Nenhum enriquecimento foi gerado.");
return [{ json: {
